<template>
  <LabeledValueIcon
    :to="isAdmin && effectiveUserId ? { name: 'users-id', params: { id: effectiveUserId } } : undefined"
    :label="displayLabel"
    :icon="roleIcon(displayUser?.role)"
    :loading="isLoading"
    :error="error ? 'Failed to get data' : undefined"
  >
    <template v-if="displayUser">
      <p class="font-medium line-clamp-1">{{ username(displayUser) }}</p>
      <span v-if="displayUser.subcontractor_company" class="text-sm text-muted-foreground line-clamp-1">
        {{ displayUser.subcontractor_company.name }}
      </span>
    </template>
  </LabeledValueIcon>
</template>
<script setup lang="ts">
import LabeledValueIcon from '~/components/common/LabeledValueIcon.vue';
import { getUserShortInfo, type UserShortInfo } from '~/client';
import { roleIcon, getUserRole } from '~/constants/users/userRoles';

// Accepts either a pre-fetched `user` (skip the request) or a `userId` to fetch by.
const props = defineProps<{
  label?: string;
  user?: UserShortInfo;
  userId?: string;
}>();

const effectiveUserId = computed(() => props.userId ?? props.user?.id);

const { data, isLoading, error } = useQuery({
  key: () => ['user.short-info', effectiveUserId.value ?? ''],
  query: () => getUserShortInfo({ composable: '$fetch', path: { user_id: effectiveUserId.value ?? '' } }),
  enabled: () => !!effectiveUserId.value && !props.user,
});

const displayUser = computed(() => props.user ?? data.value);
const displayLabel = computed(
  () => props.label || (displayUser.value?.role ? getUserRole(displayUser.value.role).name : 'User')
);

const { isAdmin } = useUserRole();
</script>
